import{_ as n,H as a,f as t,i as s}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"开篇词｜框架正在坍塌：像写操作系统一样，复刻 OpenClaw 的底层 Harness","description":"","frontmatter":{},"headers":[{"level":2,"title":"从“盲目调包”到“黑盒失控”：我们离真实的生产力有多远？","slug":"从-盲目调包-到-黑盒失控-我们离真实的生产力有多远","link":"#从-盲目调包-到-黑盒失控-我们离真实的生产力有多远","children":[]},{"level":2,"title":"认知重塑：框架正在坍塌，Harness（驾驭工程）正在崛起","slug":"认知重塑-框架正在坍塌-harness-驾驭工程-正在崛起","link":"#认知重塑-框架正在坍塌-harness-驾驭工程-正在崛起","children":[]},{"level":2,"title":"为什么是 OpenClaw？极简哲学的胜利","slug":"为什么是-openclaw-极简哲学的胜利","link":"#为什么是-openclaw-极简哲学的胜利","children":[]},{"level":2,"title":"重新定位：新范式下开发者的角色跃迁","slug":"重新定位-新范式下开发者的角色跃迁","link":"#重新定位-新范式下开发者的角色跃迁","children":[]},{"level":2,"title":"专栏模块设计：你的 Harness 架构师进阶地图","slug":"专栏模块设计-你的-harness-架构师进阶地图","link":"#专栏模块设计-你的-harness-架构师进阶地图","children":[]},{"level":2,"title":"写在最后：造轮子的意义与拥抱前沿","slug":"写在最后-造轮子的意义与拥抱前沿","link":"#写在最后-造轮子的意义与拥抱前沿","children":[]}],"relativePath":"从0开始构建AgentHarness/开篇词｜框架正在坍塌：像写操作系统一样，复刻OpenClaw的底层Harness.md","filePath":"从0开始构建AgentHarness/开篇词｜框架正在坍塌：像写操作系统一样，复刻OpenClaw的底层Harness.md","lastUpdated":1779818543000}'),o={name:"从0开始构建AgentHarness/开篇词｜框架正在坍塌：像写操作系统一样，复刻OpenClaw的底层Harness.md"};function r(p,e,i,l,g,c){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="开篇词-框架正在坍塌-像写操作系统一样-复刻-openclaw-的底层-harness" tabindex="-1">开篇词｜框架正在坍塌：像写操作系统一样，复刻 OpenClaw 的底层 Harness <a class="header-anchor" href="#开篇词-框架正在坍塌-像写操作系统一样-复刻-openclaw-的底层-harness" aria-label="Permalink to &quot;开篇词｜框架正在坍塌：像写操作系统一样，复刻 OpenClaw 的底层 Harness&quot;">​</a></h1><p>你好，我是Tony Bai。欢迎来到《从0开始构建 Agent Harness》的课堂。</p><p>在正式开启我们这场硬核的底层构建之旅前，我想先与你分享一个近乎每天都在我，或许也在你身边上演的场景。</p><p>这是一个普通的下午，你正在尝试用大模型写一个具备代码审查能力的 AI Agent。IDE 的屏幕上，是你引入的一堆庞大的第三方框架代码（比如 LangChain 或 AutoGen）；而在另一块屏幕上，是大模型的控制台或日志输出。</p><p>你的开发工作流，变成了一场在黑盒与报错之间不断妥协的 <strong>“补丁探戈”</strong>：</p><ol><li>你发现 Agent 在读取一个 3000 行的日志文件时，大模型 API 冰冷地抛出了 <code>400 Token limit exceeded</code>。于是你赶紧去翻阅框架文档，试图找到一个配置项来截断文本。</li><li>紧接着，Agent 在尝试修复一个编译报错时，陷入了死胡同。它连续 10 次执行了完全相同的、错误的 <code>bash</code> 命令，毫无察觉地在原地打转。你叹了口气，在 System Prompt 里加上一句极其苍白的警告：“千万不要陷入死循环！”</li><li>更可怕的是，由于你赋予了它执行本地 Shell 的权限，在某次幻觉中，它误解了当前的工作路径，试图执行类似 <code>rm -rf ./*</code> 的高危操作。你惊出一身冷汗，赶紧去重写正则黑名单。</li></ol><p>这些场景，你熟悉吗？</p><h2 id="从-盲目调包-到-黑盒失控-我们离真实的生产力有多远" tabindex="-1">从“盲目调包”到“黑盒失控”：我们离真实的生产力有多远？ <a class="header-anchor" href="#从-盲目调包-到-黑盒失控-我们离真实的生产力有多远" aria-label="Permalink to &quot;从“盲目调包”到“黑盒失控”：我们离真实的生产力有多远？&quot;">​</a></h2><p>自从大语言模型（LLM）的 API 开放以来，我们似乎都默认了上面这种“调包”的开发模式。我们乐此不疲地引入一层又一层的上层抽象，用几十行代码跑起一个看似无所不能的 Demo，并为之感到欣喜。</p><p>但扪心自问，当把这些基于框架拼凑出来的 Agent 投入到长周期的真实生产环境中时，它们真的可用吗？</p><p>这层阻碍我们迈向真正工业级 AI 应用的隔阂，我称之为 Agent 开发的“三大失控摩擦力”：</p><ol><li><p><strong>上下文失控</strong>：我们盲目地给模型塞入几十个工具描述，却不知道大模型的注意力会被这些冗长的系统设定严重稀释，导致“降智”和幻觉。</p></li><li><p><strong>状态失控</strong>：传统的框架在内存中维护着极其复杂的隐式状态机。一旦对话轮数过多，模型就会得“健忘症”；一旦遇到顽固报错，模型就会陷入死循环（Doom Loop）。而由于状态被框架封装在黑盒里，人类开发者根本无法在中途介入干预。</p></li><li><p><strong>边界失控</strong>：我们既希望 Agent 拥有改变物理世界的能力（执行代码、修改文件），又缺乏底层的物理拦截机制。大模型的“冲动”一旦越界，就是灾难。</p></li></ol><p>我们可以用一张图来直观感受，在传统的框架模式下，开发者是如何被这些黑盒摩擦力消耗精力的：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E6%9E%84%E5%BB%BAAgentHarness/images/967026/8yy4fdc9ff8ce7c216645ba6cc85a32f.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E6%9E%84%E5%BB%BAAgentHarness/images/967026/8yy4fdc9ff8ce7c216645ba6cc85a32f.png" alt="图片"></a></p><p>这些摩擦力的存在，让我们意识到： <strong>单纯靠堆砌 Prompt 或者调用更高层级的应用框架，是永远无法构建出工业级 Agent 的。</strong></p><p>那么，真正的解法，究竟是什么？</p><h2 id="认知重塑-框架正在坍塌-harness-驾驭工程-正在崛起" tabindex="-1">认知重塑：框架正在坍塌，Harness（驾驭工程）正在崛起 <a class="header-anchor" href="#认知重塑-框架正在坍塌-harness-驾驭工程-正在崛起" aria-label="Permalink to &quot;认知重塑：框架正在坍塌，Harness（驾驭工程）正在崛起&quot;">​</a></h2><p>要理解这场架构革命的深刻性，我们必须清晰地看到 AI Agent 演进的一条底层暗线。</p><p>在深入剖析了当今业界最顶尖的原生 Coding Agent（如 Anthropic 的 Claude Code 以及备受瞩目的开源项目 OpenClaw）后，我得到了一个极其深刻的行业洞见：</p><blockquote><p>The Framework Layer is Collapsing into the Harness.</p><p>传统的应用框架层正在加速坍塌，并逐渐融入底层的驱动工程中。</p></blockquote><p>在早期，由于大模型逻辑推理能力弱，我们需要用厚重的 Framework 去帮它做意图识别、路由分发。框架扮演的是一个“事无巨细的微管家”。但今天，面对 GPT-5.2 或 Claude 4.6 Sonnet 这样极其聪明的模型，它们原生就具备了顶级的规划（Planning）和工具调用（Function Calling）能力。此时，“微管家”式的框架反而成了阻碍。</p><p>我们需要的不再是教模型“怎么想”的抽象层，而是一个为模型提供健壮物理躯体和生存环境的 <strong>底层引擎——这就是 Harness（驾驭工程）</strong>。</p><p>我们可以用计算机体系结构来做一个最直观的类比：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E6%9E%84%E5%BB%BAAgentHarness/images/967026/5f9a32719b326c8c6362a5dafdf9896a.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E6%9E%84%E5%BB%BAAgentHarness/images/967026/5f9a32719b326c8c6362a5dafdf9896a.png" alt="图片"></a></p><p><strong>Harness 的本质，就是为大模型写一个微型操作系统（OS）。</strong> 在这个 OS 里，大模型是 CPU，上下文窗口是极其珍贵的 RAM（内存），各种本地操作是外设（硬件）。Harness 不干涉 CPU 的计算，但它必须极其严苛地管理内存回收（上下文压缩）、调度硬件接口（极简工具集）、并随时准备触发系统中断（拦截高危操作与死循环）。</p><p>大模型（CPU）决定了智力（算力）的上限，而 Harness （OS）决定了这套智力在现实世界中能发挥出几成。</p><blockquote><p>注：Harness原意为“马具/缰绳”，Harness Engineering 是指通过构建受控环境，包括设计和构建约束机制、反馈回路、工作流控制和持续改进循环等，让AI在约束下高效可靠地工作。国内多译为“驾驭工程”或“管控工程”，这里使用“驾驭工程”这种译法。</p></blockquote><h2 id="为什么是-openclaw-极简哲学的胜利" tabindex="-1">为什么是 OpenClaw？极简哲学的胜利 <a class="header-anchor" href="#为什么是-openclaw-极简哲学的胜利" aria-label="Permalink to &quot;为什么是 OpenClaw？极简哲学的胜利&quot;">​</a></h2><p>如果要构建这样一个工业级的 Agent Harness 引擎，我们需要一个顶级的学习标杆。在众多开源项目中，OpenClaw（及其底层运行时 <code>pi</code>）以其反直觉但又无比高效的设计哲学脱颖而出。</p><p>在拆解 OpenClaw 的源码时，我被它解决复杂工程问题时的“大道至简”深深折服：</p><ol><li><p><strong>极简工具法则（Minimal Toolset）</strong>：当别人都在疯狂集成包含几十个 API 的臃肿 MCP 协议时，OpenClaw 坚信大模型本身足够聪明，因此 <strong>只暴露 4 个完备的基础原语：</strong> <code>Read</code>、 <code>Write</code>、 <code>Edit</code> 和 <code>Bash</code>。只要给模型一个 <code>bash</code>，它就能自己去运行 <code>git</code>、 <code>grep</code>，甚至自己写脚本来解决问题。这就从根源上消灭了工具层面带来的上下文膨胀。</p></li><li><p><strong>状态外部化（Externalized State）</strong>：这是 OpenClaw 的神来之笔。它完全抛弃了在代码内存中维护复杂的任务状态机。相反，它强制 Agent 将数据写在工作区的Markdown文件中，比如将宏大的规划写在 <code>PLAN.md</code> 中，将微观的进度写在 <code>TODO.md</code> 中。记忆不再是黑盒，而是人类随时可以打开、阅读甚至手动修改的纯文本。这实现了真正的“零成本人机协同”。</p></li><li><p><strong>YOLO 哲学与防御纵深</strong>：在本地开发环境，它奉行 YOLO（You Only Live Once，全权信任）模式，让 Agent 自由狂奔；但同时，它又在底层埋下了坚固的安全中间件（Middleware），用于在部署到远端服务器时，瞬间挂起高危命令，等待人类的审批放行。</p></li></ol><p>这套化繁为简的 Harness 哲学，正是我们在 AI 时代最需要的工程智慧。</p><h2 id="重新定位-新范式下开发者的角色跃迁" tabindex="-1">重新定位：新范式下开发者的角色跃迁 <a class="header-anchor" href="#重新定位-新范式下开发者的角色跃迁" aria-label="Permalink to &quot;重新定位：新范式下开发者的角色跃迁&quot;">​</a></h2><p>听到这里，你可能会意识到，这场从 Framework 到 Harness 的演进，不仅是一次技术架构的升级，更是一次关于 <strong>工程师自我价值重塑</strong> 的严肃命题。</p><p>当 AI 拥有了强大的原生推理和行动能力，我们的角色将从一个“调包侠”或“Prompt 裱糊匠”，蜕变为整个 AI 物理法则的“设计者”与“驾驭者”。</p><p>你将花更多的时间思考：</p><ul><li><p>如何设计一个像 OS GC（垃圾回收）一样的阶梯掩码算法，在不丢失模型意图的前提下，榨干最后一点 Token 空间？</p></li><li><p>如何在底层构建一个安全的防线，让大模型在发疯执行 <code>rm -rf</code> 时被精准拦截？</p></li><li><p>如何为引擎建立科学的链路追踪（Tracing）和自动化度量（Benchmark）体系，用数据证明你的 Agent 真的变聪明了？</p></li></ul><p>我们不再是黑盒框架的使用者，而是成为了构筑 AI 世界秩序的系统架构师。</p><h2 id="专栏模块设计-你的-harness-架构师进阶地图" tabindex="-1">专栏模块设计：你的 Harness 架构师进阶地图 <a class="header-anchor" href="#专栏模块设计-你的-harness-架构师进阶地图" aria-label="Permalink to &quot;专栏模块设计：你的 Harness 架构师进阶地图&quot;">​</a></h2><p>为了帮助你系统地完成这次技能升级与思维跃迁，在这个专栏中，我将带你使用 Go 语言，吸收 OpenClaw 的顶级架构哲学，从零开始写出一个轻量、极简但五脏俱全的工业级 Agent Harness 引擎——我们称之为 <code>go-tiny-claw</code>。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E6%9E%84%E5%BB%BAAgentHarness/images/967026/18d1b7e15efd6827626779b1585a2ec5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E6%9E%84%E5%BB%BAAgentHarness/images/967026/18d1b7e15efd6827626779b1585a2ec5.png" alt="图片"></a></p><p>为什么选 Go？因为在构建高并发、流式通信以及底层基础设施时，Go 有着得天独厚的优势。当然，如果你是 Python 或 Rust 开发者也请放心，本专栏的核心资产是 <strong>“架构思想与驾驭逻辑”</strong>，这些底层哲学放之四海而皆准。</p><p>整个专栏被精心设计为 24 讲，划分为六个递进的章节。它就像一张清晰的系统构建图纸：</p><p><strong>第一章：认知与核心引擎（The Core Engine）</strong></p><p>我们将抛弃黑盒，纯手写大模型原生的 ReAct 循环。设计优雅的多模型适配层（接入 Claude 与OpenAI兼容 API 模型），并前瞻性地引入独立的“慢思考（Thinking）”机制，极大提升复杂任务的规划成功率。</p><p><strong>第二章：极简工具与物理交互（Action &amp; Tools）</strong></p><p>打造强扩展性的 Tool Registry。深刻贯彻极简工具哲学。手写支持多级模糊匹配的健壮 <code>Edit</code> 工具，并利用 Go 的并发特性压榨出并行工具执行的性能极限。</p><p><strong>第三章：上下文工程体系（Context Engineering）</strong></p><p>这是决定 Agent 智商的生命线。我们将实现系统提示词的动态组装、超长文本的阶梯降级压缩（Compaction）；更重要的是，摒弃复杂的内部状态机，把“记忆”与“待办”完全外部化为本地的文件系统。</p><p><strong>第四章：稳定性控制与多智能体（Safety &amp; Coordination）</strong></p><p>让 Agent 走向生产环境。实现运行时提醒（Reminders）斩断死循环；通过 Middleware 拦截危险操作，在飞书中弹出卡片等待人类审批（Human-in-the-loop）；引入 Subagent 隔离复杂任务。</p><p><strong>第五章：可观测性与科学度量（Observability &amp; Evaluation）</strong></p><p>这是高级工程师的分水岭。为引擎引入链路追踪（Tracing）、成本审计，并搭建自动化 Benchmark 评估脚本，科学量化引擎的每一次进步。</p><p><strong>第六章：端到端实战串讲（End-to-End Practice）</strong></p><p>全要素组装。我们将最终打造出一个强悍的 CLI 工具，以及一个能在飞书群里随时被召唤、具备安全底线的 AgentOps 运维自动化助手。</p><h2 id="写在最后-造轮子的意义与拥抱前沿" tabindex="-1">写在最后：造轮子的意义与拥抱前沿 <a class="header-anchor" href="#写在最后-造轮子的意义与拥抱前沿" aria-label="Permalink to &quot;写在最后：造轮子的意义与拥抱前沿&quot;">​</a></h2><p>在这个开源框架满天飞的时代，可能有人会问：“既然已经有了那么多工具，为什么我们还要从零开始造轮子？”</p><p>我的回答是： <strong>只有亲自造过轮子的人，才知道车辆在高速过弯时，底盘的极限到底在哪里。</strong></p><p>在这个被 AI 席卷的时代，一部分人可能会因为固守“调包框架”的安逸而被底层的性能瓶颈和失控所反噬；而另一部分人，则会选择主动向下深钻，学会如何像写操作系统一样驾驭这股强大的新力量。</p><p>未来已来，它就蕴藏在那些最底层的代码和极简的架构哲学中。现在，我正式邀请你，放下焦虑，带上你的键盘，与我一起开启这场硬核的底层引擎构建之旅。让我们共同见证，一个工业级的 AI Agent 引擎，是如何在你手中诞生并改变世界的。</p><p>在开篇词的最后，我还想坦诚地与大家再分享一点。</p><p>Harness Engineering（驾驭工程）是一个极其前沿且目前在业界（无论是学术界还是工业界）都处于高速演进甚至处于“野蛮生长”阶段的全新命题。</p><p>从 Anthropic 内部流出的工程实践，到开源社区 OpenClaw 的极简架构，这个领域的底层认知几乎每个月都在经历着重塑与推翻。我们今天在专栏中“奉为圭臬”的某些设计哲学，也许在未来随着大模型（如拥有更强原生规划能力）的问世，都有可能被证明存在偏颇，甚至是被完全抛弃的过渡方案。</p><p><strong>这正是拥抱前沿技术最迷人，也最具风险的地方。</strong></p><p>因此，我对这门专栏的定位绝不是一份静态文档。后续如果在业界出现了新的Harness 架构理论，或者新的优秀工业实践，我会尽量以“加餐”的形式，及时为大家带来最前沿的复盘、纠偏与源码迭代。我们第一讲见！</p>',65)])])}const A=n(o,[["render",r]]);export{h as __pageData,A as default};
